import{_ as a,C as i,o as l,c,a2 as r,E as t,j as s,a as n}from"./chunks/framework.BSaF8iZ6.js";const S=JSON.parse('{"title":"Inventory Sources","description":"","frontmatter":{},"headers":[],"relativePath":"inventory/inventory-source-management.md","filePath":"inventory/inventory-source-management.md","lastUpdated":1789411447000}'),u={name:"inventory/inventory-source-management.md"};function d(g,e,h,m,p,y){const o=i("ImagePopup");return l(),c("div",null,[e[0]||(e[0]=r('<h1 id="inventory-sources" tabindex="-1">Inventory Sources <a class="header-anchor" href="#inventory-sources" aria-label="Permalink to &quot;Inventory Sources&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>An inventory source is a place where a seller keeps stock, such as a warehouse or a shop. Stock is recorded for each source, and sellers choose a source when they ship an order.</p><p>Every shop starts with a source called <strong>Default</strong>, and sellers can add more.</p><h2 id="your-sources" tabindex="-1">Your sources <a class="header-anchor" href="#your-sources" aria-label="Permalink to &quot;Your sources&quot;">​</a></h2><p>Go to <strong>Inventories &gt;&gt; Inventory Sources</strong>. The list shows each source&#39;s <strong>ID</strong>, <strong>Code</strong>, <strong>Name</strong>, <strong>Priority</strong> and <strong>Status</strong>, with icons to edit or delete it.</p>',6)),t(o,{src:"/images/inventory-source-management/inventory-sources.png",alt:"The seller's Inventory Sources list"}),e[1]||(e[1]=r('<h2 id="add-a-source" tabindex="-1">Add a source <a class="header-anchor" href="#add-a-source" aria-label="Permalink to &quot;Add a source&quot;">​</a></h2><ol><li>Go to <strong>Inventories &gt;&gt; Inventory Sources</strong>.</li><li>Click <strong>Create Inventory Source</strong>.</li><li>In <strong>General</strong>, enter a <strong>Code</strong>, a <strong>Name</strong> and, if you like, a <strong>Description</strong>.</li><li>In <strong>Source Address</strong>, enter the <strong>Country</strong>, <strong>State</strong>, <strong>City</strong>, <strong>Street</strong> and <strong>Postcode</strong>.</li><li>In <strong>Contact Information</strong>, enter the <strong>Name</strong>, <strong>Email</strong> and <strong>Contact Number</strong> of the person in charge, and a <strong>Fax</strong> if you have one.</li><li>In <strong>Settings</strong>, enter the <strong>Latitude</strong>, <strong>Longitude</strong> and <strong>Priority</strong>, and switch <strong>Status</strong> on.</li><li>Click <strong>Save Inventory Sources</strong>.</li></ol>',2)),t(o,{src:"/images/inventory-source-management/source-create.png",alt:"The Add Inventory Source form"}),e[2]||(e[2]=r('<ul><li>The <strong>Code</strong> must be at least two characters, start with a letter, and use only letters, numbers and underscores. No other source on the marketplace, including the store&#39;s own sources, can use it.</li><li><strong>Status</strong> is off on a new source. Switch it on so the source&#39;s stock is available to customers and the source appears on your product form.</li></ul><p>You&#39;ll see <strong>Inventory Source Created Successfully</strong>. The new source is added to every channel your shop sells on. No approval is needed.</p><h2 id="edit-or-delete-a-source" tabindex="-1">Edit or delete a source <a class="header-anchor" href="#edit-or-delete-a-source" aria-label="Permalink to &quot;Edit or delete a source&quot;">​</a></h2><ul><li>Click the edit icon to change a source, then click <strong>Save Inventory Sources</strong>.</li><li>Click the delete icon to remove it. You can&#39;t delete your last active source. You&#39;ll see <strong>Last Active Inventory Sources Can Not Deleted</strong>.</li></ul><h2 id="where-sources-are-used" tabindex="-1">Where sources are used <a class="header-anchor" href="#where-sources-are-used" aria-label="Permalink to &quot;Where sources are used&quot;">​</a></h2><ul><li>Set stock for each source on a product&#39;s <strong>Inventories</strong> step, or for many products in <a href="./manage-inventory">Manage Inventory</a>.</li><li>Choose the source an order ships from when you create a shipment. Pickups are scheduled from that source. See <a href="./../orders/fulfilment-carriers">Shipments &amp; Carriers</a>.</li></ul><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Configure &gt;&gt; Inventory Sources</strong> to see the sources of every seller, with their <strong>Id</strong>, <strong>Code</strong>, <strong>Name</strong>, <strong>Seller Name</strong>, <strong>Business Name</strong> and <strong>Status</strong>. Click the icon on a row to see the source&#39;s details. Sellers manage their own sources, so this list is read-only.</p>',8)),t(o,{src:"/images/inventory-source-management/admin-inventory-sources.png",alt:"The admin's read-only list of seller inventory sources"}),e[3]||(e[3]=s("p",null,[n("Your store's own sources, under "),s("strong",null,"Settings >> Inventory Sources"),n(", don't include seller sources.")],-1))])}const _=a(u,[["render",d]]);export{S as __pageData,_ as default};
